CREATE TABLE events (
    id BIGSERIAL PRIMARY KEY,
    user_id INT,
    event_time TIMESTAMPTZ,
    properties JSONB  -- JSONB: binary JSON, indexable
);
-- Query JSON field
SELECT user_id, properties->>'page' AS page, properties->>'duration' AS duration
FROM events
WHERE properties->>'event_type' = 'page_view'
  AND (properties->>'duration')::int > 30;
-- Index on JSON field
CREATE INDEX ON events ((properties->>'user_segment'));

-- pgvector: store and search embeddings
CREATE EXTENSION vector;
CREATE TABLE documents (id INT, content TEXT, embedding vector(1536));
CREATE INDEX ON documents USING hnsw (embedding vector_cosine_ops);
-- Nearest neighbour search
SELECT id, content, 1 - (embedding <=> '[0.1, 0.2, ...]'::vector) AS similarity
FROM documents
ORDER BY embedding <=> '[0.1, 0.2, ...]'::vector
LIMIT 10;

-- LATERAL join: for each user, get their last 5 orders
SELECT u.user_id, o.order_id, o.revenue
FROM users u
CROSS JOIN LATERAL (
    SELECT * FROM orders
    WHERE user_id = u.user_id
    ORDER BY order_date DESC LIMIT 5
) o;

-- COPY for bulk data loading (much faster than INSERT)
COPY training_data FROM '/data/features.csv' CSV HEADER;
